regras.b1.02.001:
:host {
  display: block;
  width: 100%;
  color: var(--text, #172033);
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}

regras.b1.03.001:
.app-header {
  min-height: 64px;
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) 42px;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}

regras.b1.03.002:
.app-menu-button,
.app-notifications {
  width: 40px;
  height: 40px;
  display: grid;
  place-content: center;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #fff;
  cursor: pointer;
}

regras.b1.03.004:
.app-menu-button span {
  width: 20px;
  height: 2px;
  border-radius: 9px;
  background: currentColor;
}

regras.b1.03.005:
.app-brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}

regras.b1.03.006:
.app-brand img {
  width: 28px;
  height: 28px;
  object-fit: contain;
  filter: brightness(0) invert(1);
}

regras.b1.03.009:
.app-brand-copy strong {
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-size:16px;
  letter-spacing:-.02em;
}

regras.b1.03.010:
.app-brand-copy small {
  margin-top:1px;
  font-size:9px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
  opacity:.72;
}

regras.b1.03.012:
.app-notifications svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

regras.b1.03.013:
.app-notifications-badge {
  position:absolute;
  top:4px;
  right:2px;
  min-width:16px;
  height:16px;
  padding:0 4px;
  display:grid;
  place-items:center;
  border:2px solid var(--primary);
  border-radius:999px;
  background:#ef4444;
  color:#fff;
  font-size:9px;
  font-weight:800;
}

regras.b1.05.003:
.appointments-eyebrow {
  display: block;
  margin-bottom: 6px;
  color: var(--gold);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

regras.b1.05.004:
.appointments-head h1 {
  margin: 0;
  color: var(--primary);
  font-size: 24px;
  line-height: 1.15;
  letter-spacing: -.025em;
}

regras.b1.05.005:
.appointments-head p {
  max-width: 580px;
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
}

regras.b1.05.006:
.appointments-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 6px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #f8fafc;
}

regras.b1.05.007:
.appointments-tabs button {
  min-width: 0;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #667085;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

regras.b1.05.008:
.appointments-tabs button b {
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: #e9eef5;
  color: #475467;
  font-size: 10px;
}

regras.b1.05.009:
.appointments-tabs button.is-active {
  background: #fff;
  color: var(--primary);
  box-shadow: 0 1px 4px rgba(16,35,63,.10);
}

regras.b1.05.016:
.appointment-card {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fff;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  box-shadow: 0 2px 7px rgba(16,35,63,.035);
}

regras.b1.05.019:
.appointment-topline {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

regras.b1.05.021:
.status {
  display: inline-flex;
  min-height: 23px;
  align-items: center;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .035em;
  text-transform: uppercase;
}

regras.b1.05.026:
.appointment-card strong {
  display: block;
  margin-top: 4px;
  color: #344054;
  font-size: 12px;
}

regras.b1.05.027:
.appointment-card p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
}

regras.b1.06.001:
.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

regras.b1.06.003:
.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

regras.b1.06.004:
.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

regras.b1.06.005:
.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

regras.b1.06.006:
.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

regras.b1.06.007:
.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

regras.b1.06.010:
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}

regras.b1.06.011:
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

regras.b1.06.012:
.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}

regras.b1.06.016:
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}

regras.b1.06.022:
.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}

regras.b1.06.025:
.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}

regras.b1.06.028:
.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}

regras.b1.06.030:
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}

regras.b1.06.033:
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
